{"command":"@'
const fs = require('node:fs');
const path = require('node:path');
const WebSocket = require('ws');

const WS_URL = 'ws://127.0.0.1:9090';
const PROMPT = '调用trae开发一个电商平台搭建一套具备侧边栏、动效路由、复杂暗黑模式的电商看板 Dashboard 基座代码结构，必须包含至少 5 个复杂的业务级复用组件！';
const MAX_ATTEMPTS = 3;
const ACTION_TIMEOUT_MS = 25000;
const OBSERVE_MS_AFTER_SUCCESS = 180000;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function now() {
  return new Date().toISOString();
}

function createRecorder(logFile) {
  const records = [];
  return {
    push(type, payload) {
      const item = { ts: now(), type, payload };
      records.push(item);
      try {
        fs.appendFileSync(logFile, JSON.stringify(item, null, 2) + '\n');
      } catch {}
    },
    list() {
      return records;
    }
  };
}

function waitForOpen(ws, timeoutMs = 10000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('open timeout'));
    }, timeoutMs);

    const onOpen = () => {
      cleanup();
      resolve();
    };

    const onErr = (e) => {
      cleanup();
      reject(e);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('open', onOpen);
      ws.off('error', onErr);
    }

    ws.on('open', onOpen);
    ws.on('error', onErr);
  });
}

function waitForMessage(ws, predicate, timeoutMs) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('message timeout'));
    }, timeoutMs);

    const onMsg = (raw) => {
      let msg;
      try {
        msg = JSON.parse(raw.toString());
      } catch {
        return;
      }
      if (!predicate(msg)) {
        return;
      }
      cleanup();
      resolve(msg);
    };

    const onErr = (e) => {
      cleanup();
      reject(e);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('message', onMsg);
      ws.off('error', onErr);
    }

    ws.on('message', onMsg);
    ws.on('error', onErr);
  });
}

function send(ws, payload, recorder, note) {
  recorder.push('send', { note, payload });
  ws.send(JSON.stringify(payload));
}

async function executeCommand(ws, command, args, recorder) {
  send(ws, { action: 'execute_command', command, args: args || [] }, recorder, `execute_command:${command}`);
  const res = await waitForMessage(
    ws,
    (m) => m.type === 'command_result' && m.command === command,
    ACTION_TIMEOUT_MS
  );
  recorder.push('recv', res);
  return res;
}

async function triggerTask(ws, attempt, recorder) {
  const payload = {
    action: 'trigger_task',
    subagent: 'frontend-architect',
    prompt: PROMPT
  };
  send(ws, payload, recorder, `trigger_task_attempt_${attempt}`);
  const receipt = await waitForMessage(ws, (m) => m.type === 'action_receipt', ACTION_TIMEOUT_MS);
  recorder.push('recv', receipt);
  return receipt;
}

async function main() {
  const stamp = new Date().toISOString().replace(/[T:.]/g, '-').slice(0, 19);
  const logFile = path.resolve(__dirname, `.tmp/live_real_task_${stamp}.jsonl`);
  const summaryFile = path.resolve(__dirname, `.tmp/live_real_task_${stamp}_summary.json`);
  const recorder = createRecorder(logFile);

  const ws = new WebSocket(WS_URL);
  let closed = false;

  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      if (msg.type === 'file_saved' || msg.type === 'system_diagnostics_report') {
        recorder.push('stream', msg);
      }
    } catch {}
  });

  ws.on('close', () => {
    closed = true;
    recorder.push('socket', { event: 'close' });
  });

  try {
    await waitForOpen(ws, 10000);
    recorder.push('socket', { event: 'open' });

    const connected = await waitForMessage(ws, (m) => m.type === 'connected', 10000);
    recorder.push('recv', connected);

    // preflight: try to open chat context first
    await executeCommand(ws, 'workbench.action.chat.openInSidebar', [], recorder);
    await sleep(600);
    await executeCommand(ws, 'workbench.action.chat.newChat', [], recorder);
    await sleep(500);
    await executeCommand(ws, 'workbench.action.chat.openInSidebar', [], recorder);
    await sleep(500);

    let finalReceipt = null;
    let attempts = 0;
    while (attempts < MAX_ATTEMPTS) {
      attempts += 1;
      const receipt = await triggerTask(ws, attempts, recorder);
      finalReceipt = receipt;

      if (receipt.status === 'success') {
        break;
      }

      // fallback strategy when focus issue occurs
      if (String(receipt.message || '').includes('focus') && attempts < MAX_ATTEMPTS) {
        await executeCommand(ws, 'workbench.action.chat.openInSidebar', [], recorder);
        await sleep(700);
        await executeCommand(ws, 'workbench.action.chat.newChat', [], recorder);
        await sleep(700);
        continue;
      }

      if (attempts < MAX_ATTEMPTS) {
        await sleep(1000);
      }
    }

    let observeStart = null;
    if (finalReceipt && finalReceipt.status === 'success') {
      observeStart = Date.now();
      recorder.push('observe', { message: 'start stream observe', durationMs: OBSERVE_MS_AFTER_SUCCESS });
      await sleep(OBSERVE_MS_AFTER_SUCCESS);
      recorder.push('observe', { message: 'end stream observe' });
    }

    const all = recorder.list();
    const fileSavedEvents = all.filter((r) => r.type === 'stream' && r.payload.type === 'file_saved');
    const diagEvents = all.filter((r) => r.type === 'stream' && r.payload.type === 'system_diagnostics_report');
    const receipts = all.filter((r) => r.type === 'recv' && r.payload.type === 'action_receipt').map((r) => r.payload);

    const summary = {
      startedAt: all[0]?.ts || now(),
      finishedAt: now(),
      wsUrl: WS_URL,
      prompt,
      attempts,
      finalReceipt,
      allReceipts: receipts,
      fileSavedCount: fileSavedEvents.length,
      diagnosticsCount: diagEvents.length,
      observedMs: observeStart ? OBSERVE_MS_AFTER_SUCCESS : 0,
      logFile,
      notes: [
        'file_saved/system_diagnostics_report 仅在 Trae 实际写文件或产生诊断时上报',
        '若 finalReceipt 为 error 且含 focus，表示当前 UI 焦点上下文不足'
      ]
    };

    fs.writeFileSync(summaryFile, JSON.stringify(summary, null, 2), 'utf8');
    console.log(JSON.stringify(summary, null, 2));
  } catch (error) {
    const failure = {
      finishedAt: now(),
      error: String(error),
      logFile
    };
    const summaryFile = path.resolve(__dirname, `.tmp/live_real_task_${stamp}_summary.json`);
    fs.writeFileSync(summaryFile, JSON.stringify(failure, null, 2), 'utf8');
    console.log(JSON.stringify(failure, null, 2));
    process.exitCode = 1;
  } finally {
    if (!closed && ws.readyState === WebSocket.OPEN) {
      ws.close();
      await sleep(200);
    }
  }
}

main();
