{"command":"@'
const fs = require('node:fs');
const path = require('node:path');
const WebSocket = require('ws');

const PROMPT = '调用trae开发一个电商平台搭建一套具备侧边栏、动效路由、复杂暗黑模式的电商看板 Dashboard 基座代码结构，必须包含至少 5 个复杂的业务级复用组件！';
const OBSERVE_MS = 180000;

function now(){ return new Date().toISOString(); }
function sleep(ms){ return new Promise(r=>setTimeout(r,ms)); }

function waitOpen(ws, t=10000){
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{c();reject(new Error('open timeout'));},t);
    const onOpen=()=>{c();resolve();};
    const onErr=(e)=>{c();reject(e);};
    function c(){ clearTimeout(timer); ws.off('open',onOpen); ws.off('error',onErr); }
    ws.on('open',onOpen); ws.on('error',onErr);
  });
}

function waitMsg(ws,p,t=20000){
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{c();reject(new Error('msg timeout'));},t);
    const onMsg=(raw)=>{ try{ const m=JSON.parse(raw.toString()); if(p(m)){ c(); resolve(m); } }catch{} };
    const onErr=(e)=>{ c(); reject(e); };
    function c(){ clearTimeout(timer); ws.off('message',onMsg); ws.off('error',onErr); }
    ws.on('message',onMsg); ws.on('error',onErr);
  });
}

async function execCommand(ws, command, args, logs){
  const payload = { action:'execute_command', command, args: args ?? [] };
  logs.push({ ts: now(), type:'send', payload });
  ws.send(JSON.stringify(payload));
  const res = await waitMsg(ws, m=>m.type==='command_result' && m.command===command, 25000);
  logs.push({ ts: now(), type:'recv', payload: res });
  return res;
}

(async()=>{
  const stamp = new Date().toISOString().replace(/[T:.]/g,'-').slice(0,19);
  const logPath = path.resolve(__dirname, `live_real_task_alt_${stamp}.json`);
  const logs = [];

  const ws = new WebSocket('ws://127.0.0.1:9090');

  ws.on('message', (raw)=>{
    try{
      const m=JSON.parse(raw.toString());
      if(m.type==='file_saved' || m.type==='system_diagnostics_report'){
        logs.push({ ts: now(), type:'stream', payload:m });
      }
    }catch{}
  });

  try{
    await waitOpen(ws);
    logs.push({ ts: now(), type:'socket', payload:{event:'open'} });

    const connected = await waitMsg(ws, m=>m.type==='connected', 10000);
    logs.push({ ts: now(), type:'recv', payload: connected });

    await execCommand(ws, 'workbench.action.chat.newChat', [], logs);
    await sleep(400);
    await execCommand(ws, 'workbench.action.chat.sendToNewChat', [PROMPT], logs);
    await sleep(400);
    await execCommand(ws, 'workbench.action.chat.submitWithCodebase', [], logs);

    logs.push({ ts: now(), type:'observe', payload:{start:true, ms:OBSERVE_MS} });
    await sleep(OBSERVE_MS);
    logs.push({ ts: now(), type:'observe', payload:{end:true} });

    const fileSaved = logs.filter(x=>x.type==='stream' && x.payload.type==='file_saved');
    const diags = logs.filter(x=>x.type==='stream' && x.payload.type==='system_diagnostics_report');

    const summary = {
      startedAt: logs[0]?.ts,
      finishedAt: now(),
      method: 'execute_command chat.sendToNewChat + submitWithCodebase',
      prompt: PROMPT,
      fileSavedCount: fileSaved.length,
      diagnosticsCount: diags.length,
      sampleSavedFiles: fileSaved.slice(0, 10).map(x=>x.payload.file),
      logPath
    };

    fs.writeFileSync(logPath, JSON.stringify({ summary, logs }, null, 2), 'utf8');
    console.log(JSON.stringify(summary, null, 2));
  } catch (e) {
    const summary = { finishedAt: now(), error: String(e), logPath };
    fs.writeFileSync(logPath, JSON.stringify({ summary, logs }, null, 2), 'utf8');
    console.log(JSON.stringify(summary, null, 2));
    process.exitCode = 1;
  } finally {
    if(ws.readyState===WebSocket.OPEN){ ws.close(); }
  }
})();
