function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function now() {
  return new Date().toISOString();
}

function recursiveFileCount(dir) {
  if (!fs.existsSync(dir)) {
    return 0;
  }
  let count = 0;
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop();
    const entries = fs.readdirSync(current, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) {
        stack.push(full);
      } else if (entry.isFile()) {
        count += 1;
      }
    }
  }
  return count;
}

function listSampleFiles(dir, limit = 20) {
  if (!fs.existsSync(dir)) {
    return [];
  }
  const files = [];
  const stack = [dir];
  while (stack.length && files.length < limit) {
    const current = stack.pop();
    const entries = fs.readdirSync(current, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) {
        stack.push(full);
      } else if (entry.isFile()) {
        files.push(full.replace(/\\/g, '/'));
        if (files.length >= limit) {
          break;
        }
      }
    }
  }
  return files;
}

function waitForOpen(ws, timeoutMs = STEP_TIMEOUT) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('open timeout'));
    }, timeoutMs);

    const onOpen = () => {
      cleanup();
      resolve();
    };

    const onErr = (e) => {
      cleanup();
      reject(e);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('open', onOpen);
      ws.off('error', onErr);
    }

    ws.on('open', onOpen);
    ws.on('error', onErr);
  });
}

function waitForMessage(ws, predicate, timeoutMs = STEP_TIMEOUT) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error('message timeout'));
    }, timeoutMs);

    const onMsg = (raw) => {
      let msg;
      try {
        msg = JSON.parse(raw.toString());
      } catch {
        return;
      }
      if (!predicate(msg)) {
        return;
      }
      cleanup();
      resolve(msg);
    };

    const onErr = (e) => {
      cleanup();
      reject(e);
    };

    function cleanup() {
      clearTimeout(timer);
      ws.off('message', onMsg);
      ws.off('error', onErr);
    }

    ws.on('message', onMsg);
    ws.on('error', onErr);
  });
}

async function sendWithRetry(label, fn, timeline) {
  let lastError = null;
  for (let i = 0; i < MAX_RETRY; i += 1) {
    const attempt = i + 1;
    try {
      timeline.push({ ts: now(), type: 'retry_attempt', label, attempt, remaining: MAX_RETRY - attempt });
      return await fn(attempt);
    } catch (e) {
      lastError = String(e);
      timeline.push({ ts: now(), type: 'retry_error', label, attempt, error: String(e) });
      if (attempt < MAX_RETRY) {
        await sleep(BACKOFF[i]);
      }
    }
  }
  throw new Error(`${label} failed after ${MAX_RETRY} retries: ${lastError}`);
}

function buildTaskPrompt(task, selectedModel) {
  const card = {
    wave_id: task.wave,
    task_id: task.taskId,
    objective: task.objective,
    required_skills: task.required_skills,
    acceptance: task.acceptance,
    risk_level: task.risk_level,
    target_directory: TARGET_DIR,
    preferred_model: selectedModel,
    constraints: [
      '必须创建可运行的 Dashboard 基座代码',
      '必须包含侧边栏、动效路由、复杂暗黑模式',
      '必须包含至少5个业务级复用组件',
      '禁止询问用户，直接执行并落盘'
    ]
  };

  return [
    '你是 Trae 执行端，请严格按下面任务卡开发并把代码写入目标目录。',
    'TASK_CARD_JSON:',
    JSON.stringify(card, null, 2),
    '执行完成后请自行进行最小可行验证（至少 npm install + npm run build 或等价命令）。'
  ].join('\n');
}

async function selectModel(ws, task, timeline) {
  const payload = {
    action: 'auto_select_model',
    prompt: `${task.wave}-${task.taskId}:${task.objective}`,
    modeHint: task.modeHint,
    dryRun: false
  };

  ws.send(JSON.stringify(payload));
  const res = await waitForMessage(ws, (m) => m.type === 'model_selection_result', STEP_TIMEOUT);
  timeline.push({
    ts: now(),
    type: 'model_selection',
    taskId: task.taskId,
    status: res.status,
    intent: res?.data?.intent,
    selectedModel: res?.data?.selectedModel,
    setConfigSucceeded: res?.data?.setConfigSucceeded
  });
  return res;
}

async function dispatchTask(ws, task, selectedModel, timeline) {
  const prompt = buildTaskPrompt(task, selectedModel);

  // primary path: trigger_task
  const primary = await sendWithRetry(`trigger_task_${task.taskId}`, async (attempt) => {
    ws.send(JSON.stringify({
      action: 'trigger_task',
      subagent: task.subagent,
      prompt
    }));

    const receipt = await waitForMessage(ws, (m) => m.type === 'action_receipt', STEP_TIMEOUT);
    timeline.push({ ts: now(), type: 'action_receipt', taskId: task.taskId, attempt, receipt });

    if (receipt.status === 'success') {
      return { method: 'trigger_task', receipt };
    }

    if (String(receipt.message || '').includes('focus')) {
      throw new Error(`focus issue: ${receipt.message}`);
    }

    throw new Error(`trigger_task error: ${receipt.message}`);
  }, timeline).catch(async (primaryError) => {
    timeline.push({ ts: now(), type: 'fallback_start', taskId: task.taskId, reason: String(primaryError) });

    // fallback path using execute_command chat chain
    const runCommand = async (command, args = []) => {
      ws.send(JSON.stringify({ action: 'execute_command', command, args }));
      const res = await waitForMessage(ws, (m) => m.type === 'command_result' && m.command === command, STEP_TIMEOUT);
      timeline.push({ ts: now(), type: 'command_result', taskId: task.taskId, command, status: res.status, error: res.error || null });
      if (res.status !== 'success') {
        throw new Error(`${command} failed: ${res.error || 'unknown'}`);
      }
    };

    await runCommand('workbench.action.chat.newChat', []);
    await sleep(400);
    await runCommand('workbench.action.chat.sendToNewChat', [prompt]);
    await sleep(400);
    await runCommand('workbench.action.chat.submitWithCodebase', []);

    return { method: 'execute_command_fallback', receipt: { status: 'success', message: 'submitted via fallback chain' } };
  });

  return primary;
}

async function observeStream(ws, ms, timeline, summaryState) {
  const endAt = Date.now() + ms;

  const onMessage = (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      if (msg.type === 'file_saved') {
        summaryState.fileSaved += 1;
        summaryState.savedFiles.add(msg.file);
        timeline.push({ ts: now(), type: 'file_saved', file: msg.file });
      } else if (msg.type === 'system_diagnostics_report') {
        summaryState.diagnostics += 1;
        timeline.push({ ts: now(), type: 'diagnostics', count: Array.isArray(msg.data) ? msg.data.length : 0 });
      }
    } catch {}
  };

  ws.on('message', onMessage);
  while (Date.now() < endAt) {
    await sleep(500);
  }
  ws.off('message', onMessage);
}

async function main() {
  const timeline = [];
  const summaryState = {
    fileSaved: 0,
    diagnostics: 0,
    savedFiles: new Set()
  };

  const beforeCount = recursiveFileCount(TARGET_DIR);

  const ws = new WebSocket(WS_URL);
  let connected = false;

  try {
    await waitForOpen(ws);
    connected = true;
    timeline.push({ ts: now(), type: 'socket_open', url: WS_URL });

    const hello = await waitForMessage(ws, (m) => m.type === 'connected', STEP_TIMEOUT);
    timeline.push({ ts: now(), type: 'socket_connected', message: hello.message });

    // Wave execution
    for (const task of tasks) {
      // preflight skill binding validation
      if (!Array.isArray(task.required_skills) || task.required_skills.length === 0) {
        throw new Error(`preflight blocked: ${task.taskId} missing required_skills`);
      }

      timeline.push({
        ts: now(),
        type: 'task_start',
        wave: task.wave,
        taskId: task.taskId,
        subagent: task.subagent,
        required_skills: task.required_skills,
        timeoutSec: STEP_TIMEOUT / 1000,
        maxRetry: MAX_RETRY
      });

      const modelRes = await selectModel(ws, task, timeline);
      const selectedModel = modelRes?.data?.selectedModel || null;

      if (!selectedModel) {
        throw new Error(`paused: no available model for ${task.taskId}`);
      }

      if (modelRes?.data?.setConfigSucceeded === false && modelRes?.status === 'partial') {
        timeline.push({
          ts: now(),
          type: 'model_partial',
          taskId: task.taskId,
          note: 'model switch unverified, continue with selectedModel in task prompt'
        });
      }

      const dispatchRes = await dispatchTask(ws, task, selectedModel, timeline);
      timeline.push({ ts: now(), type: 'task_dispatched', wave: task.wave, taskId: task.taskId, method: dispatchRes.method });

      // observe each task window
      await observeStream(ws, 30000, timeline, summaryState);
      timeline.push({ ts: now(), type: 'task_observe_done', taskId: task.taskId });
    }

    const afterCount = recursiveFileCount(TARGET_DIR);
    const summary = {
      status: 'success',
      startedAt: timeline[0]?.ts || now(),
      finishedAt: now(),
      concurrency_limit: 8,
      step_timeout_sec: 20,
      retry_limit: 3,
      waves: ['A', 'B', 'C'],
      tasks_total: tasks.length,
      file_count_before: beforeCount,
      file_count_after: afterCount,
      file_count_delta: afterCount - beforeCount,
      stream_file_saved_count: summaryState.fileSaved,
      stream_diagnostics_count: summaryState.diagnostics,
      stream_saved_files_sample: Array.from(summaryState.savedFiles).slice(0, 20),
      target_dir_exists: fs.existsSync(TARGET_DIR),
      target_dir_sample_files: listSampleFiles(TARGET_DIR, 30),
      timeline
    };

    console.log(JSON.stringify(summary, null, 2));
  } catch (e) {
    const afterCount = recursiveFileCount(TARGET_DIR);
    const fail = {
      status: 'paused',
      reason: String(e),
      startedAt: timeline[0]?.ts || now(),
      finishedAt: now(),
      file_count_before: beforeCount,
      file_count_after: afterCount,
      file_count_delta: afterCount - beforeCount,
      stream_file_saved_count: summaryState.fileSaved,
      stream_diagnostics_count: summaryState.diagnostics,
      target_dir_exists: fs.existsSync(TARGET_DIR),
      target_dir_sample_files: listSampleFiles(TARGET_DIR, 30),
      timeline
    };
    console.log(JSON.stringify(fail, null, 2));
    process.exitCode = 2;
  } finally {
    if (connected && ws.readyState === WebSocket.OPEN) {
      ws.close();
      await sleep(200);
    }
  }
}

