const OBSERVE_MS = 240000;
const STEP_TIMEOUT = 25000;

const PROMPT = [
  '请直接开发并落盘，不要提问。',
  `目标目录: ${TARGET}`,
  '任务: 创建一个电商看板 Dashboard 基座，技术栈 React + TypeScript + Vite + Tailwind + React Router + Framer Motion。',
