function sleep(ms){ return new Promise(r=>setTimeout(r,ms)); }
function now(){ return new Date().toISOString(); }

function fileCount(dir){
  if(!fs.existsSync(dir)) return 0;
  let c=0; const stack=[dir];
  while(stack.length){
    const d=stack.pop();
    for(const e of fs.readdirSync(d,{withFileTypes:true})){
      const f=path.join(d,e.name);
      if(e.isDirectory()) stack.push(f);
      else if(e.isFile()) c++;
    }
  }
  return c;
}

function listFiles(dir, limit=60){
  if(!fs.existsSync(dir)) return [];
  const out=[]; const stack=[dir];
  while(stack.length && out.length<limit){
    const d=stack.pop();
    for(const e of fs.readdirSync(d,{withFileTypes:true})){
      const f=path.join(d,e.name);
      if(e.isDirectory()) stack.push(f);
      else if(e.isFile()) {
        out.push(f.replace(/\\/g,'/'));
        if(out.length>=limit) break;
      }
    }
  }
  return out;
}

function waitOpen(ws, timeout=STEP_TIMEOUT){
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{cleanup(); reject(new Error('open timeout'));}, timeout);
    const onOpen=()=>{cleanup(); resolve();};
    const onErr=(e)=>{cleanup(); reject(e);};
    function cleanup(){clearTimeout(timer); ws.off('open',onOpen); ws.off('error',onErr);}    
    ws.on('open',onOpen); ws.on('error',onErr);
  });
}

function waitMsg(ws, predicate, timeout=STEP_TIMEOUT){
  return new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>{cleanup(); reject(new Error('msg timeout'));}, timeout);
    const onMsg=(raw)=>{
      let msg;
      try{ msg=JSON.parse(raw.toString()); }catch{return;}
      if(!predicate(msg)) return;
      cleanup();
      resolve(msg);
    };
    const onErr=(e)=>{ cleanup(); reject(e); };
    function cleanup(){clearTimeout(timer); ws.off('message',onMsg); ws.off('error',onErr);}    
    ws.on('message',onMsg); ws.on('error',onErr);
  });
}

async function exec(ws, command, args=[], logs){
  const payload={action:'execute_command',command,args};
  logs.push({ts:now(), type:'send', payload});
  ws.send(JSON.stringify(payload));
  const res=await waitMsg(ws,m=>m.type==='command_result' && m.command===command, STEP_TIMEOUT);
  logs.push({ts:now(), type:'recv', payload:res});
  return res;
}

async function run(){
  const before = fileCount(TARGET);
  const logs=[];
  const stream=[];
  const ws = new WebSocket(WS_URL);

  ws.on('message',(raw)=>{
    try{
      const msg=JSON.parse(raw.toString());
      if(msg.type==='file_saved' || msg.type==='system_diagnostics_report'){
        stream.push({ts:now(),msg});
      }
    }catch{}
  });

  let finalReceipt=null;

  try{
    await waitOpen(ws);
    logs.push({ts:now(),type:'socket_open'});
    const hello=await waitMsg(ws,m=>m.type==='connected',10000);
    logs.push({ts:now(),type:'connected',payload:hello});

    // model select
    ws.send(JSON.stringify({action:'auto_select_model', prompt:PROMPT, modeHint:'coding', dryRun:false}));
    const model=await waitMsg(ws,m=>m.type==='model_selection_result', STEP_TIMEOUT);
    logs.push({ts:now(), type:'model_selection', payload:model});

    // focus prep
    await exec(ws,'workbench.action.chat.icube.open',[],logs);
    await exec(ws,'workbench.panel.chat.view.ai-chat.open',[],logs);
    await exec(ws,'workbench.panel.chat.view.ai-chat.focus',[],logs);
    await exec(ws,'workbench.action.chat.newChat',[],logs);

    // primary
    ws.send(JSON.stringify({action:'trigger_task', subagent:'frontend-architect', prompt:PROMPT}));
    finalReceipt = await waitMsg(ws,m=>m.type==='action_receipt', STEP_TIMEOUT);
    logs.push({ts:now(), type:'action_receipt', payload:finalReceipt});

    if(finalReceipt.status!=='success'){
      // fallback dispatch
      await exec(ws,'workbench.action.chat.sendToNewChat',[PROMPT],logs);
      await exec(ws,'workbench.action.chat.submitWithCodebase',[],logs);
      finalReceipt = {type:'action_receipt', status:'success', message:'fallback_submitted'};
    }

    // keep applying possible edits during observe window
    const t0 = Date.now();
    while(Date.now() - t0 < OBSERVE_MS){
      await sleep(15000);
      try { await exec(ws,'chatEditing.acceptAllFiles',[],logs); } catch {}
    }

  } catch(e){
    logs.push({ts:now(), type:'error', error:String(e)});
  } finally {
    if(ws.readyState===WebSocket.OPEN) ws.close();
  }

  const after = fileCount(TARGET);
  const files = listFiles(TARGET, 100);

  const summary = {
    startedAt: logs[0]?.ts || now(),
    finishedAt: now(),
    target: TARGET,
    before,
    after,
    delta: after-before,
    finalReceipt,
    streamFileSaved: stream.filter(x=>x.msg.type==='file_saved').length,
    streamDiagnostics: stream.filter(x=>x.msg.type==='system_diagnostics_report').length,
    fileSavedSample: stream.filter(x=>x.msg.type==='file_saved').slice(0,20),
    files,
    logsTail: logs.slice(-30)
  };

  console.log(JSON.stringify(summary,null,2));
}

run();
